// Distancia por el círculo máximo (el camino más corto sobre la esfera) desde Buenos Aires.
const rad = (g) => (g * Math.PI) / 180;
function km(a, b) {
  const R = 6371; // radio medio de la Tierra
  const h = Math.sin(rad(b[0] - a[0]) / 2) ** 2 +
    Math.cos(rad(a[0])) * Math.cos(rad(b[0])) * Math.sin(rad(b[1] - a[1]) / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
const BA = [-34.60, -58.38];
const sitios = { "São Paulo": [-23.55, -46.63], "Ashburn": [39.04, -77.49], "Frankfurt": [50.11, 8.68], "Singapur": [1.35, 103.82] };
for (const [n, p] of Object.entries(sitios)) {
  const d = km(BA, p);
  const ida_y_vuelta = (2 * d / 200000) * 1000; // la luz en fibra: unos 200.000 km/s
  console.log(n.padEnd(10), Math.round(d).toString().padStart(6), "km  >=", ida_y_vuelta.toFixed(1), "ms de ida y vuelta");
}
